        rechnen: v => v['vg-mittel'] * v['vg-flaeche'],
        formel: 'Mittlerer Vergleichspreis je Quadratmeter mal Wohnflaeche',
        warum: 'Jetzt ruft der Narr seinen Preis aus. Das ist Schritt 1 nach Paragraf 6 Absatz 3: das nackte Rechenergebnis.',
